; seek_u16_u8_dda: exact "move object toward target" (bulk Bresenham DDA)
;
; GENERATED by tools/generate_seek_sources.py from tools/seek_kernel.py; the
; C64 Math Library installs the same kernel as MATH_SEEK16_*.
;
; x is unsigned 16-bit (sprite X, or world coordinates), y is an unsigned
; byte; |dx| <= 32767.
;
; Speed: MATH-style Q8.8 pixels per frame. SPL = fraction, SPH bits 0-6 =
; integer part (0..126). SPH bit 7 selects the speed meaning:
;   0  speed along the MAJOR axis (classic Bresenham: a 45 degree move covers
;      sqrt(2) x the distance per frame)
;   1  speed along the path (constant Euclidean speed, within 0.7%)
;
; Every frame's position is on the Bresenham line from the start to the target
; (within 0.5 px of the true line) and the object lands exactly on the target.
; Each frame moves the major axis by k = floor or ceil of the speed and the
; minor axis by the exact Bresenham amount for k pixels, precomputed at init as
; k*dmin = whole_k*dmaj + rem_k. One counter R = dmaj*256 - 1 - speeds so far
; carries both the speed fraction (borrow out of its low byte: this frame moves
; k0+1) and the distance (borrow out of the top: arrival).
;
; X = slot (0..7) for every entry and is preserved; A/Y are volatile; D=0 is
; required. The start position is whatever POS_* holds for the slot. The
; steppers return C=1 on the frame the target is reached and on every later
; call (the position stays on the target), else C=0; they use no scratch.
; Init returns C=1 if the object is already on the target, else C=0.
; Use one stepper per move: STEP (any speed), STEP_INT (major-axis integer
; speed >= 1 with bit 7 clear; ignores the fraction) or STEP1 (init with speed
; $0100; exactly 1 px/frame; uses NMOS DCP).
;
; Entries: seek16_init, seek16_step, seek16_step_int, seek16_step1.
;
; Inputs (IO block): IN_XL/IN_XH = target x, IN_Y = target y,
; IN_SPL/IN_SPH = speed. Inputs are preserved.
;
; Configure before assembly:
;   ORG  code origin
;   IO   24 bytes: inputs at +0..+4, init scratch at +5.. (zero page
;        recommended)
;   ST   248 bytes of per-slot state, 8-byte aligned (NSLOT = 8)
; The object position is S16_POS_XL, S16_POS_XH, S16_POS_Y+slot.
!cpu 6510
ORG = $8000
IO  = $E0
ST  = $9000

SEEK_IN_X   = IO+0
SEEK_IN_XH  = IO+1
SEEK_IN_Y   = IO+2
SEEK_IN_SPL = IO+3
SEEK_IN_SPH = IO+4
SEEK_T      = IO+5
SK_EMAJ   = SEEK_T+0
SK_EMIN   = SEEK_T+1
SK_Q      = SEEK_T+2
SK_PH     = SEEK_T+3
SK_SPH    = SEEK_T+4
SK_MX     = SEEK_T+5
SK_MY     = SEEK_T+6
SK_MODE   = SEEK_T+7
SK_WHOLE  = SEEK_T+8
SK_UN     = SEEK_T+9
SK_SGN    = SEEK_T+10
SK_VMAJ   = SEEK_T+11
SK_T      = SEEK_T+12
SK_DMAJL  = SEEK_T+13
SK_DMAJH  = SEEK_T+14
SK_DMIN   = SEEK_T+15
SK_REML   = SEEK_T+16
SK_REMH   = SEEK_T+17
SK_REM8   = SEEK_T+18

S16_POS_XL  = ST+0
S16_POS_XH  = ST+8
S16_POS_Y   = ST+16
S16_TGT_XL  = ST+24
S16_TGT_XH  = ST+32
S16_TGT_Y   = ST+40
S16_RL      = ST+48
S16_RM      = ST+56
S16_RH      = ST+64
S16_ERRL    = ST+72
S16_ERRH    = ST+80
S16_DMAJL   = ST+88
S16_DMAJH   = ST+96
S16_KF      = ST+104
S16_KI      = ST+112
S16_REML    = ST+120
S16_REMH    = ST+136
S16_VXL     = ST+152
S16_VXH     = ST+184
S16_VY      = ST+216

* = ORG

; ---- SEEK16 per-frame steppers ----
seek16_step1:
        lda #$FF
        !byte $DF, <S16_RM, >S16_RM  ; DCP S16_RM,X
        bne s16_move0           ; C=1
        !byte $DF, <S16_RH, >S16_RH  ; DCP S16_RH,X: RM wrapped, borrow up
        bne s16_move0           ; Z=1 only when RH wrapped (arrival)
s16_arrive:
        lda S16_TGT_XL,x        ; land exactly on the target
        sta S16_POS_XL,x
        lda S16_TGT_XH,x
        sta S16_POS_XH,x
        lda S16_TGT_Y,x
        sta S16_POS_Y,x
s16_arrived:
        lda #0                  ; R = 0 and k0 = 1: every later call borrows
        sta S16_RM,x            ; out of RH and snaps again
        sta S16_RH,x
        lda #1
        sta S16_KI,x
        sec
        rts
s16_borrow0:                    ; RM borrowed: take it from RH (rare)
        dec S16_RH,x
        bmi s16_arrive
        sec
        jmp s16_move0
seek16_step:
        lda S16_RL,x            ; R -= speed; low borrow: this frame moves k0+1
        sec
        sbc S16_KF,x
        sta S16_RL,x
        bcc s16_set1
seek16_step_int:
        sec
        lda S16_RM,x
        sbc S16_KI,x
        sta S16_RM,x
        bcc s16_borrow0
s16_move0:
        lda S16_ERRL,x          ; C=1: err -= rem_k (16-bit)
        sbc S16_REML,x
        sta S16_ERRL,x
        lda S16_ERRH,x
        sbc S16_REMH,x
        bcc s16_wrap0
        sta S16_ERRH,x
        lda S16_POS_XL,x        ; C=1 into VX; VY absorbs the carry out
        adc S16_VXL,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY,x
        sta S16_POS_Y,x
        clc
        rts
s16_wrap0:
        tay                     ; err += dmaj
        lda S16_ERRL,x
        adc S16_DMAJL,x
        sta S16_ERRL,x
        tya
        adc S16_DMAJH,x
        sta S16_ERRH,x          ; C=1
        lda S16_POS_XL,x
        adc S16_VXL+16,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+16,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+16,x
        sta S16_POS_Y,x
        clc
        rts
s16_set1:
        lda S16_RM,x            ; C=0: subtracts k0+1
        sbc S16_KI,x
        sta S16_RM,x
        bcc s16_borrow1
s16_move1:
        lda S16_ERRL,x
        sbc S16_REML+8,x
        sta S16_ERRL,x
        lda S16_ERRH,x
        sbc S16_REMH+8,x
        bcc s16_wrap1
        sta S16_ERRH,x
        lda S16_POS_XL,x
        adc S16_VXL+8,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+8,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+8,x
        sta S16_POS_Y,x
        clc
        rts
s16_wrap1:
        tay
        lda S16_ERRL,x
        adc S16_DMAJL,x
        sta S16_ERRL,x
        tya
        adc S16_DMAJH,x
        sta S16_ERRH,x
        lda S16_POS_XL,x
        adc S16_VXL+24,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+24,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+24,x
        sta S16_POS_Y,x
        clc
        rts
s16_borrow1:                    ; RM borrowed: take it from RH (rare)
        dec S16_RH,x
        bpl s16_b1ok
        jmp s16_arrive
s16_b1ok:
        sec
        jmp s16_move1

; ---- SEEK16 init ----
seek16_init:
        lda #$FF
        sta S16_RL,x
        ldy #0
        lda SEEK_IN_Y
        sta S16_TGT_Y,x
        sec
        sbc S16_POS_Y,x
        bcs s16i_dy
        eor #$FF
        adc #1                  ; C=0
        dey
s16i_dy:
        sta SK_DMIN
        sty SK_MY
        ldy #0
        lda SEEK_IN_X
        sta S16_TGT_XL,x
        sec
        sbc S16_POS_XL,x
        sta SK_DMAJL
        lda SEEK_IN_XH
        sta S16_TGT_XH,x
        sbc S16_POS_XH,x
        bcs s16i_dx
        eor #$FF                ; |dx| = ~dx + 1; C=0 here
        sta SK_DMAJH
        lda SK_DMAJL
        eor #$FF
        adc #1
        sta SK_DMAJL
        bcc s16i_dxn
        inc SK_DMAJH
s16i_dxn:
        dey
        lda SK_DMAJH
s16i_dx:
        sta SK_DMAJH
        sty SK_MX
        bne s16i_xmaj           ; |dx| >= 256 > |dy|
        lda SK_DMAJL
        cmp SK_DMIN
        bcs s16i_xmaj
        ldy SK_DMIN             ; y major: dmaj = |dy|, dmin = |dx|
        sta SK_DMIN
        sty SK_DMAJL
        lda SK_MX
        ora #1
        sta SK_UN
        lda #$80
        bne s16i_mode
s16i_xmaj:
        lda SK_MY
        ora #1
        sta SK_UN
        lda #0
s16i_mode:
        sta SK_MODE
        lda SK_DMAJH
        sta S16_DMAJH,x
        lsr
        sta S16_ERRH,x          ; err = dmaj/2
        lda SK_DMAJL
        sta S16_DMAJL,x
        ror
        sta S16_ERRL,x
        lda SK_DMAJL            ; RH:RM:RL = dmaj*256-1
        sec
        sbc #1
        sta S16_RM,x
        lda SK_DMAJH
        sbc #0
        sta S16_RH,x
        bcc s16i_zero
        lda SEEK_IN_SPH
        bmi s16i_euclid
        sta S16_KI,x
        lda SEEK_IN_SPL
        sta S16_KF,x
s16i_rates:
        lda #0                  ; rem0 = k0*dmin mod dmaj (16-bit)
        sta SK_REML
        sta SK_REMH
        sta SK_WHOLE
        ldy S16_KI,x
        beq s16i_r0done
s16i_r0:
        jsr s16_addmin
        dey
        bne s16i_r0
s16i_r0done:
        lda SK_REML
        sta S16_REML,x
        lda SK_REMH
        sta S16_REMH,x
        txa
        tay
        lda S16_KI,x
        jsr s16_planes
        lda S16_KF,x
        beq s16i_done
        jsr s16_addmin          ; k0+1
        lda SK_REML
        sta S16_REML+8,x
        lda SK_REMH
        sta S16_REMH+8,x
        txa
        ora #8
        tay
        lda S16_KI,x
        sec
        adc #0
        jsr s16_planes
s16i_done:
        clc
        rts
s16i_zero:
        jmp s16_arrived         ; C=1
s16i_euclid:
        lda SK_DMAJH            ; scale dmaj below 256 for an 8-bit ratio
        sta SK_T
        lda SK_DMIN
        sta SK_EMIN
        lda SK_DMAJL
        ldy SK_T
s16i_scale:
        beq s16i_scaled
        lsr SK_T
        ror
        lsr SK_EMIN
        ldy SK_T
        jmp s16i_scale
s16i_scaled:
        sta SK_EMAJ
        jsr seek_euclid_speed   ; A = integer, Y = fraction
        sta S16_KI,x
        tya
        sta S16_KF,x
        jmp s16i_rates

; ---- SEEK16 helpers ----
; rem += dmin; if rem >= dmaj: rem -= dmaj, whole++.  Preserves X/Y.
s16_addmin:
        lda SK_REML
        clc
        adc SK_DMIN
        sta SK_REML
        bcc s16a_nc
        inc SK_REMH
s16a_nc:
        cmp SK_DMAJL
        lda SK_REMH
        sbc SK_DMAJH
        bcc s16a_done
        sta SK_REMH
        lda SK_REML
        sbc SK_DMAJL
        sta SK_REML
        inc SK_WHOLE
s16a_done:
        rts

; As s8_planes, with a 16-bit x delta: VXH is the sign byte of VX.
s16_planes:
        bit SK_MODE
        bmi s16p_ymaj
        eor SK_MX
        clc
        sbc SK_MX
        sta S16_VXL,y
        sta S16_VXL+16,y
        ora #$7F
        bmi s16p_xs
        lda #0
s16p_xs:
        sta S16_VXH,y
        sta S16_VXH+16,y
        sta SK_SGN
        lda SK_WHOLE
        eor SK_MY
        sec
        sbc SK_MY
        clc
        adc SK_SGN
        sta S16_VY,y
        clc
        adc SK_UN
        sta S16_VY+16,y
        rts
s16p_ymaj:
        eor SK_MY
        sec
        sbc SK_MY
        sta SK_VMAJ
        lda SK_WHOLE
        eor SK_MX
        clc
        sbc SK_MX
        sta S16_VXL,y
        sta SK_T
        ora #$7F
        bmi s16p_y0
        lda #0
s16p_y0:
        sta S16_VXH,y
        clc
        adc SK_VMAJ
        sta S16_VY,y
        lda SK_T
        clc
        adc SK_UN
        sta S16_VXL+16,y
        ora #$7F
        bmi s16p_y1
        lda #0
s16p_y1:
        sta S16_VXH+16,y
        clc
        adc SK_VMAJ
        sta S16_VY+16,y
        rts

; ---- shared: Euclidean speed -> major-axis speed ----
; In: SK_EMAJ >= 1 and SK_EMIN <= SK_EMAJ (8-bit magnitudes), speed in
; SEEK_IN_SPL/SEEK_IN_SPH (bit 7 ignored). Out: A = integer, Y = fraction of
; speed*cos(atan(dmin/dmaj)) = speed - (speed*d >> 8), d = seek_cos_d[q],
; q = min(31, floor(32*dmin/dmaj)). Preserves X.
seek_euclid_speed:
        lda SEEK_IN_SPH
        and #$7F
        sta SK_SPH
        lda #$08                ; quotient sentinel: 5 rols push it into C
        sta SK_Q
        lda SK_EMIN
seu_div:
        asl
        bcs seu_sub
        cmp SK_EMAJ
        bcc seu_skip
seu_sub:
        sbc SK_EMAJ
        sec
seu_skip:
        rol SK_Q
        bcc seu_div
        ldy SK_Q
        lda #0
        sta SK_PH
        lda seek_cos_d,y        ; d leaves LSB first; the sentinel in bit 7
        sec                     ; ends the loop after 8 shifts
        ror
        sta SK_Q
        lda #0
seu_mul:
        bcc seu_mskip
        clc
        adc SEEK_IN_SPL
        tay
        lda SK_PH
        adc SK_SPH
        sta SK_PH
        tya
seu_mskip:
        ror SK_PH
        ror
        lsr SK_Q
        bne seu_mul
        sta SK_Q                ; speed - P
        lda SEEK_IN_SPL
        sec
        sbc SK_Q
        tay
        lda SK_SPH
        sbc SK_PH
        rts

; cos_d[q] = round(256*(1-cos(atan((q+0.5)/32))))
seek_cos_d:
        !byte 0, 0, 1, 2, 2, 4, 5, 7
        !byte 9, 11, 13, 15, 18, 20, 23, 26
        !byte 28, 31, 34, 37, 40, 44, 47, 50
        !byte 53, 56, 59, 62, 65, 68, 71, 74
